"""Compare the OpenAPI document generated by the application with `docs/api-spec.yml`.

Scope (task 4.2): for the selected paths, the methods, the response status codes, the names of the
multipart form fields and the property names (and required list) of the schemas used in the
responses. Descriptions, examples and header details are not compared: they are prose.
"""

from collections.abc import Iterable, Mapping
from pathlib import Path
from typing import Any
from urllib.parse import urlparse

import yaml

from tests.db_support import BACKEND_DIR

SPEC_PATH = BACKEND_DIR.parent / "docs" / "api-spec.yml"
HTTP_METHODS = ("get", "put", "post", "delete", "options", "head", "patch", "trace")

Document = Mapping[str, Any]


def load_spec(path: Path = SPEC_PATH) -> Document:
    loaded = yaml.safe_load(path.read_text(encoding="utf-8"))
    assert isinstance(loaded, dict)
    return loaded


def server_prefix(spec: Document) -> str:
    """Path prefix of the first server, for example `/api/v1`."""
    return urlparse(str(spec["servers"][0]["url"])).path.rstrip("/")


def resolve(document: Document, node: Any) -> Any:
    """Follow local `$ref` links until a concrete node is reached."""
    seen = 0
    while isinstance(node, Mapping) and "$ref" in node:
        reference = str(node["$ref"])
        assert reference.startswith("#/"), reference
        target: Any = document
        for part in reference[2:].split("/"):
            target = target[part]
        node = target
        seen += 1
        assert seen < 20, "reference loop"
    return node


def operations(document: Document, path: str) -> dict[str, Mapping[str, Any]]:
    item = resolve(document, document["paths"].get(path, {}))
    return {method: item[method] for method in HTTP_METHODS if method in item}


def status_codes(document: Document, operation: Mapping[str, Any]) -> set[str]:
    return {str(code) for code in operation.get("responses", {})}


def schema_names(document: Document, schema: Any) -> set[str]:
    """Property names of an object schema, following references."""
    resolved = resolve(document, schema)
    if not isinstance(resolved, Mapping):
        return set()
    return {str(name) for name in resolved.get("properties", {})}


def schema_required(document: Document, schema: Any) -> set[str]:
    resolved = resolve(document, schema)
    if not isinstance(resolved, Mapping):
        return set()
    return {str(name) for name in resolved.get("required", [])}


def form_fields(document: Document, operation: Mapping[str, Any]) -> set[str] | None:
    body = resolve(document, operation.get("requestBody"))
    if not isinstance(body, Mapping):
        return None
    content = body.get("content", {})
    form = content.get("multipart/form-data")
    if form is None:
        return None
    return schema_names(document, form.get("schema"))


def json_schemas(document: Document, operation: Mapping[str, Any]) -> list[Any]:
    """The JSON response schemas of an operation (items of an array response are unwrapped)."""
    schemas: list[Any] = []
    for response in operation.get("responses", {}).values():
        resolved = resolve(document, response)
        content = resolved.get("content", {}) if isinstance(resolved, Mapping) else {}
        schema = content.get("application/json", {}).get("schema")
        if schema is None:
            continue
        concrete = resolve(document, schema)
        if isinstance(concrete, Mapping) and concrete.get("type") == "array":
            schema = concrete.get("items")
        schemas.append(schema)
    return schemas


def contract_differences(
    spec: Document,
    actual: Document,
    paths: Iterable[str],
    prefix: str,
    schema_name: str = "Document",
) -> list[str]:
    """Human-readable differences between the contract and the application document."""
    differences: list[str] = []
    for path in paths:
        expected_ops = operations(spec, path)
        actual_ops = operations(actual, prefix + path)
        if set(expected_ops) != set(actual_ops):
            differences.append(
                f"{path}: methods {sorted(actual_ops)} differ from the contract "
                f"{sorted(expected_ops)}"
            )
        for method in sorted(set(expected_ops) & set(actual_ops)):
            where = f"{method.upper()} {path}"
            expected_codes = status_codes(spec, expected_ops[method])
            actual_codes = status_codes(actual, actual_ops[method])
            if expected_codes != actual_codes:
                differences.append(
                    f"{where}: status codes {sorted(actual_codes)} differ from the contract "
                    f"{sorted(expected_codes)}"
                )
            expected_form = form_fields(spec, expected_ops[method])
            actual_form = form_fields(actual, actual_ops[method])
            if expected_form != actual_form:
                differences.append(
                    f"{where}: form fields {actual_form} differ from the contract {expected_form}"
                )
    expected_names = schema_names(spec, {"$ref": f"#/components/schemas/{schema_name}"})
    actual_schema = {"$ref": f"#/components/schemas/{schema_name}"}
    try:
        actual_names = schema_names(actual, actual_schema)
        actual_required = schema_required(actual, actual_schema)
    except KeyError:
        actual_names, actual_required = set(), set()
    if expected_names != actual_names:
        differences.append(
            f"{schema_name}: fields {sorted(actual_names)} differ from the contract "
            f"{sorted(expected_names)}"
        )
    expected_required = schema_required(spec, {"$ref": f"#/components/schemas/{schema_name}"})
    if expected_required != actual_required:
        differences.append(
            f"{schema_name}: required {sorted(actual_required)} differ from the contract "
            f"{sorted(expected_required)}"
        )
    return differences
